package com.eec.bookhub.controller;
import com.eec.bookhub.model.*;import com.eec.bookhub.repository.*;import com.eec.bookhub.service.CurrentUserService;import jakarta.servlet.http.HttpSession;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/reviews")
public class ReviewController {private final ReviewRepository repo;private final BorrowingRepository borrowings;private final CurrentUserService current;public ReviewController(ReviewRepository repo,BorrowingRepository borrowings,CurrentUserService current){this.repo=repo;this.borrowings=borrowings;this.current=current;}
@GetMapping public List<Review> all(){return repo.findAllByOrderByDateDesc();} @PostMapping public Review add(@RequestBody Review r,HttpSession s){User u=current.require(s);if(r.rating==null||r.rating<1||r.rating>5)throw new IllegalArgumentException("Rating must be between 1 and 5.");boolean borrowed=borrowings.findByBorrowerIdOrProviderIdOrderByBorrowDateDesc(u.id,u.id).stream().anyMatch(b->b.borrowerId.equals(u.id)&&b.bookId.equals(r.bookId));if(!borrowed)throw new IllegalArgumentException("You can review only books you have borrowed.");if(repo.existsByBookIdAndUserId(r.bookId,u.id))throw new IllegalArgumentException("You already reviewed this book.");r.id="rv_"+UUID.randomUUID().toString().replace("-","").substring(0,12);r.userId=u.id;r.userName=u.name;r.date=java.time.Instant.now();return repo.save(r);} }
